WITH desired AS (SELECT pb.id_user,pb.id_record,RANK() OVER(ORDER BY r.time)::integer AS level_position FROM public.personal_best_global pb JOIN public.record r ON r.id=pb.id_record WHERE pb.id_level=1 AND NOT EXISTS(SELECT 1 FROM zc_private.record_validation v WHERE v.id_record=r.id AND v.status='fail')) SELECT count(*) FROM desired FULL JOIN (SELECT * FROM public.user_point_contribution WHERE id_level=1) actual USING(id_user) WHERE ROW(desired.id_record,desired.level_position) IS DISTINCT FROM ROW(actual.id_record,actual.level_position)
